#pragma once
/* What a pet is to the firmware: its frames, animations, mood sets, colours and play looks. The built-in dolphin
 * (sprites.c, generated by tools/petpack.py) and a pet pack loaded from flash (pet_pack.c) both fill one of these. */
#include <stdint.h>
#include "lvgl.h"

#define PET_SPRITE_W 48
#define PET_SPRITE_H 40

typedef struct { uint16_t img; int8_t dx; int8_t dy; uint16_t ms; } pet_frame_t;
typedef struct { const char *name; const pet_frame_t *frames; uint16_t count; } pet_anim_t;
typedef struct { uint16_t anim; uint8_t weight; } pet_idle_choice_t;

enum { PET_MOOD_SAD, PET_MOOD_NEUTRAL, PET_MOOD_HAPPY, PET_MOOD_ECSTATIC, PET_MOOD_WORRIED, PET_MOOD_CLASSES };
enum { PET_REACT_CELEBRATE, PET_REACT_NOTICE, PET_REACT_SLEEP, PET_REACTIONS };

typedef struct {
    uint32_t ink, sleep_ink, background, panel, dim, accent, warn, good;   /* 0xRRGGBB */
} pet_colors_t;

typedef struct {
    const char *name;
    pet_colors_t colors;
    const lv_image_dsc_t *const *images;   /* A8, PET_SPRITE_W x PET_SPRITE_H */
    uint16_t image_count;
    const pet_anim_t *anims;
    uint16_t anim_count;
    uint16_t reaction[PET_REACTIONS];      /* index in anims of celebrate, notice and sleep */
    uint16_t rest[PET_MOOD_CLASSES];       /* image shown between animations */
    const pet_idle_choice_t *idle[PET_MOOD_CLASSES];
    uint8_t idle_len[PET_MOOD_CLASSES];    /* at least 1 each */
    pet_anim_t snack, heart;               /* play looks: fed, petted */
    uint32_t pads[4];                      /* Pet Says pad colours */
} pet_def_t;
